arguments.file_text:
@using sv_49021bf7a1e745a995bca9d2dd08d102.Models
@inject ISettingsService SettingsService

<div class="profile-section">
    @if (isLoading)
    {
        <div class="text-center p-4">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else if (profile is not null)
    {
        <h4 class="mb-4">Profile Settings</h4>

        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
                @statusMessage
                <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label fw-semibold">Display Name</label>
                    <input type="text" class="form-control" @bind="editDisplayName" />
                </div>

                <div class="mb-3">
                    <label class="form-label fw-semibold">Email</label>
                    <input type="email" class="form-control" @bind="editEmail" />
                </div>

                <div class="mb-3">
                    <label class="form-label fw-semibold">Bio</label>
                    <textarea class="form-control" rows="4" @bind="editBio"></textarea>
                </div>
            </div>

            <div class="col-md-4">
                <div class="avatar-preview text-center">
                    <label class="form-label fw-semibold">Avatar Preview</label>
                    <div class="avatar-frame mb-2">
                        @if (!string.IsNullOrWhiteSpace(editAvatarUrl))
                        {
                            <img src="@editAvatarUrl" alt="Avatar" class="avatar-img" />
                        }
                        else
                        {
                            <div class="avatar-placeholder">👤</div>
                        }
                    </div>
                    <small class="text-muted text-break">@editAvatarUrl</small>
                </div>
            </div>
        </div>

        <div class="d-flex gap-2 mt-3">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                @if (isSaving)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                }
                Save Changes
            </button>
            <button class="btn btn-outline-secondary" @onclick="DiscardChanges" disabled="@isSaving">
                Discard Changes
            </button>
        </div>
    }
</div>

@code {
    private UserProfile? profile;
    private string editDisplayName = "";
    private string editEmail = "";
    private string editBio = "";
    private string editAvatarUrl = "";
    private bool isLoading = true;
    private bool isSaving;
    private string? statusMessage;
    private bool isError;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        isLoading = true;
        profile = await SettingsService.GetProfileAsync();
        PopulateFields(profile);
        isLoading = false;
    }

    private void PopulateFields(UserProfile p)
    {
        editDisplayName = p.DisplayName;
        editEmail = p.Email;
        editBio = p.Bio;
        editAvatarUrl = p.AvatarUrl;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        statusMessage = null;
        try
        {
            var updated = new UserProfile(editDisplayName, editEmail, editAvatarUrl, editBio);
            await SettingsService.SaveProfileAsync(updated);
            profile = updated;
            statusMessage = "Profile saved successfully!";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to save profile: {ex.Message}";
            isError = true;
        }
        finally
        {
            isSaving = false;
        }
    }

    private void DiscardChanges()
    {
        if (profile is not null)
        {
            PopulateFields(profile);
            statusMessage = null;
        }
    }
}

.avatar-preview {
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 0.5rem;
    border: 1px solid #dee2e6;
}

.avatar-frame {
    width: 120px;
    height: 120px;
    margin: 0 auto;
    border-radius: 50%;
    overflow: hidden;
    border: 3px solid #dee2e6;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #fff;
}

.avatar-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    font-size: 3rem;
    color: #adb5bd;
}

@using sv_49021bf7a1e745a995bca9d2dd08d102.Models
@inject ISettingsService SettingsService

<div class="notifications-section">
    @if (isLoading)
    {
        <div class="text-center p-4">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else if (prefs is not null)
    {
        <h4 class="mb-4">Notification Preferences</h4>

        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
                @statusMessage
                <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <div class="card mb-4">
            <div class="card-body">
                <h6 class="card-title mb-3">General</h6>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" role="switch" id="emailNotif"
                           @bind="editEmailNotifications" />
                    <label class="form-check-label" for="emailNotif">Email Notifications</label>
                </div>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" role="switch" id="pushNotif"
                           @bind="editPushNotifications" />
                    <label class="form-check-label" for="pushNotif">Push Notifications</label>
                </div>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" role="switch" id="weeklyDigest"
                           @bind="editWeeklyDigest" />
                    <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
                </div>
            </div>
        </div>

        <div class="card mb-4">
            <div class="card-body">
                <h6 class="card-title mb-3">Muted Channels</h6>

                @if (allChannels.Count == 0)
                {
                    <p class="text-muted">No channels available.</p>
                }
                else
                {
                    @foreach (var channel in allChannels)
                    {
                        <div class="form-check mb-2">
                            <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                                   checked="@editMutedChannels.Contains(channel)"
                                   @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                            <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
                        </div>
                    }
                }
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
            @if (isSaving)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Save Preferences
        </button>
    }
</div>

@code {
    /// <summary>
    /// The full list of available channel names. The component uses this to render
    /// checkboxes, marking the ones present in the user's MutedChannels as checked.
    /// </summary>
    [Parameter]
    public List<string> AvailableChannels { get; set; } = ["general", "announcements", "engineering", "design", "marketing", "support", "random"];

    private NotificationPrefs? prefs;
    private bool editEmailNotifications;
    private bool editPushNotifications;
    private bool editWeeklyDigest;
    private HashSet<string> editMutedChannels = [];
    private List<string> allChannels = [];
    private bool isLoading = true;
    private bool isSaving;
    private string? statusMessage;
    private bool isError;

    protected override async Task OnInitializedAsync()
    {
        allChannels = AvailableChannels;
        isLoading = true;
        prefs = await SettingsService.GetNotificationPrefsAsync();
        editEmailNotifications = prefs.EmailNotifications;
        editPushNotifications = prefs.PushNotifications;
        editWeeklyDigest = prefs.WeeklyDigest;
        editMutedChannels = [.. prefs.MutedChannels];
        isLoading = false;
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            editMutedChannels.Add(channel);
        else
            editMutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        statusMessage = null;
        try
        {
            var updated = new NotificationPrefs(
                editEmailNotifications,
                editPushNotifications,
                editWeeklyDigest,
                editMutedChannels.ToList());
            await SettingsService.SaveNotificationPrefsAsync(updated);
            prefs = updated;
            statusMessage = "Notification preferences saved!";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to save preferences: {ex.Message}";
            isError = true;
        }
        finally
        {
            isSaving = false;
        }
    }
}

