@code {
    private AppearanceSettings? currentSettings;
    private string editTheme = "Light";
    private string editFontSize = "Medium";
    private string editLanguage = "en";
    private bool editCompactMode;
    private bool isLoading = true;
    private bool isSaving;
    private string? statusMessage;
    private bool isError;

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        currentSettings = await SettingsService.GetAppearanceAsync();
        editTheme = currentSettings.Theme;
        editFontSize = currentSettings.FontSize;
        editLanguage = currentSettings.Language;
        editCompactMode = currentSettings.CompactMode;
        isLoading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        if (editTheme == "Dark")
            classes.Add("preview-dark");
        if (editCompactMode)
            classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private string GetPreviewTextStyle()
    {
        var size = editFontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        return $"font-size: {size};";
    }

    private string GetPreviewHeadingStyle()
    {
        var size = editFontSize switch
        {
            "Small" => "1.1rem",
            "Large" => "1.5rem",
            _ => "1.25rem"
        };
        return $"font-size: {size};";
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        statusMessage = null;
        try
        {
            var updated = new AppearanceSettings(editTheme, editFontSize, editLanguage, editCompactMode);
            await SettingsService.SaveAppearanceAsync(updated);
            currentSettings = updated;
            statusMessage = "Appearance settings saved!";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to save settings: {ex.Message}";
            isError = true;
        }
        finally
        {
            isSaving = false;
        }
    }
}

