{"file_text": "@using sv_49021bf7a1e745a995bca9d2dd08d102.Models
@inject ISettingsService SettingsService

<div class="appearance-section">
    @if (isLoading)
    {
        <div class="text-center p-4">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <h4 class="mb-4">Appearance Settings</h4>

        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
                @statusMessage
                <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <div class="row">
            <div class="col-md-6">
                @* Theme *@
                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title">Theme</h6>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{theme}")" value="@theme"
                                       checked="@(editTheme == theme)"
                                       @onchange="() => editTheme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>
                </div>

                @* Font Size *@
                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title">Font Size</h6>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"fs-{size}")" value="@size"
                                       checked="@(editFontSize == size)"
                                       @onchange="() => editFontSize = size" />
                                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                            </div>
                        }
                    </div>
                </div>

                @* Language *@
                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title">Language</h6>
                        <select class="form-select" @bind="editLanguage">
                            <option value="en">English</option>
                            <option value="es">Spanish</option>
                            <option value="fr">French</option>
                            <option value="de">German</option>
                            <option value="ja">Japanese</option>
                            <option value="zh">Chinese</option>
                        </select>
                    </div>
                </div>

                @* Compact Mode *@
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" role="switch" id="compactMode"
                                   @bind="editCompactMode" />
                            <label class="form-check-label" for="compactMode">Compact Mode</label>
                        </div>
                        <small class="text-muted">Reduces spacing and padding for a denser layout.</small>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                    @if (isSaving)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    }
                    Save
                </button>
            </div>

            @* Live Preview *@
            <div class="col-md-6">
                <div class="card">
                    <div class="card-header">
                        <h6 class="mb-0">Live Preview</h6>
                    </div>
                    <div class="card-body preview-area @GetPreviewClasses()">
                        <h5 style="@GetPreviewHeadingStyle()">Sample Heading</h5>
                        <p style="@GetPreviewTextStyle()">
                            This is how your content will look with the selected appearance settings.
                            The preview updates as you change options.
                        </p>
                        <div class="d-flex gap-2 mt-3 @(editCompactMode ? "mb-1" : "mb-3")">
                            <button class="btn btn-sm btn-primary">Primary</button>
                            <button class="btn btn-sm btn-outline-secondary">Secondary</button>
                        </div>
                        <ul style="@GetPreviewTextStyle()" class="@(editCompactMode ? "mb-0" : "")">
                            <li>List item one</li>
                            <li>List item two</li>
                            <li>List item three</li>
                        </ul>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private AppearanceSettings? currentSettings;
    private string editTheme = "Light";
    private string editFontSize = "Medium";
    private string editLanguage = "en";
    private bool editCompactMode;
    private bool isLoading = true;
    private bool isSaving;
    private string? statusMessage;
    private bool isError;

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        currentSettings = await SettingsService.GetAppearanceAsync();
        editTheme = currentSettings.Theme;
        editFontSize = currentSettings.FontSize;
        editLanguage = currentSettings.Language;
        editCompactMode = currentSettings.CompactMode;
        isLoading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        if (editTheme == "Dark")
            classes.Add("preview-dark");
        if (editCompactMode)
            classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private string GetPreviewTextStyle()
    {
        var size = editFontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        return $"font-size: {size};";
    }

    private string GetPreviewHeadingStyle()
    {
        var size = editFontSize switch
        {
            "Small" => "1.1rem",
            "Large" => "1.5rem",
            _ => "1.25rem"
        };
        return $"font-size: {size};";
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        statusMessage = null;
        try
        {
            var updated = new AppearanceSettings(editTheme, editFontSize, editLanguage, editCompactMode);
            await SettingsService.SaveAppearanceAsync(updated);
            currentSettings = updated;
            statusMessage = "Appearance settings saved!";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Failed to save settings: {ex.Message}";
            isError = true;
        }
        finally
        {
            isSaving = false;
        }
    }
}
